  // Chat failure copy: localized render of chat_error.message, keyed by chat_error.copy_key
  'chat_error.codex_session_expired':
    'Sua sessão do Codex expirou. Reconecte-a em Configurações → Integrações.',
  'chat_error.session_expired': 'Sua sessão do OpenHuman expirou. Entre novamente para continuar.',
  'chat_error.action_budget':
    'Você atingiu o limite de ações por hora do OpenHuman. É um teto de segurança local, não do seu provedor de IA. A janela se recupera aos poucos; você pode continuar conversando neste tópico e as etapas que usam muitas ferramentas voltarão conforme o limite for reposto.',
  'chat_error.max_iterations':
    'O agente executou o número máximo de etapas de ferramentas em um turno sem concluir. Isso geralmente significa que uma ferramenta continuou falhando (muitas vezes por um limite de requisições em uma busca na web). Você pode repetir a mesma pergunta neste tópico quando o limite for liberado.',
  'chat_error.turn_timeout':
    'Este turno passou do limite de tempo sem concluir e foi interrompido para não travar. Isso geralmente significa que uma chamada de ferramenta ou um subagente delegado travou. Você pode repetir sua pergunta neste tópico.',
  'chat_error.empty_response':
    'O modelo retornou uma resposta vazia. Tente novamente. Se continuar acontecendo, tente outro modelo ou confira a configuração dele em Conexões → Chaves de API → LLM.',
  'chat_error.chat_template_rejected':
    'O modelo de chat deste modelo rejeitou a requisição. Não é culpa do modelo, da temperatura nem da sua chave de API. Modelos locais sem chamada nativa de ferramentas usam o próprio modelo de chat, e alguns recusam o formato da mensagem de uma etapa de ferramenta. Inicie um novo chat para redefinir o histórico ou escolha um modelo com suporte nativo a ferramentas em Conexões → Chaves de API → LLM.',
  'chat_error.rate_limited':
    'Seu provedor de IA está limitando as requisições. É um limite temporário do provedor, não um bloqueio do tópico. Você pode tentar novamente neste tópico.',
  'chat_error.rate_limited_billing':
    'Seu provedor de IA está recusando requisições por motivos de cobrança ou de plano (sem créditos, limite do plano ou modelo indisponível). Tentar de novo não vai ajudar. Abra Configurações para recarregar, melhorar seu plano ou escolher outro modelo.',
  'chat_error.managed_rate_limited':
    'Seu provedor de IA está limitando as requisições. Você pode tentar novamente neste tópico.',
  'chat_error.timeout': 'A requisição expirou. Verifique sua conexão e tente novamente.',
  'chat_error.auth_error':
    'Há um problema de autenticação com o provedor de IA. Verifique sua chave de API nas configurações.',
  'chat_error.budget_exhausted':
    'Você ficou sem créditos, então não consigo executar o modelo gerenciado (na nuvem) agora. Você pode recarregar créditos ou escolher um plano para continuar. Ou, se ativou um modelo local como o Ollama, mude o roteamento para "Use seus próprios modelos" em Conexões → Chaves de API → LLM.',
  'chat_error.managed_budget_exhausted':
    "Você ficou sem créditos. Recarregue ou mude para 'Use seus próprios modelos' em Configurações.",
  'chat_error.provider_unavailable':
    'O provedor de IA está temporariamente indisponível. Tente novamente mais tarde.',
  'chat_error.managed_unavailable':
    'O serviço de IA está temporariamente indisponível. Fomos notificados. Tente novamente em instantes.',
  'chat_error.payload_too_large':
    'Sua mensagem ou anexo é grande demais para este modelo. Encurte-a ou remova o anexo, ou inicie um novo tópico.',
  'chat_error.context_overflow': 'A conversa está longa demais. Inicie um novo chat.',
  'chat_error.model_config_rejected':
    'Seu provedor de IA rejeitou o modelo ou a temperatura da requisição. Confira o modelo e o roteamento em Configurações → LLM.',
  'chat_error.model_unavailable':
    'O modelo selecionado não está disponível no seu provedor. Confira as configurações do modelo.',
  'chat_error.capability_unsupported':
    'Este modelo não consegue processar imagens. Remova o anexo ou mude para um modelo com suporte a visão em Conexões → Chaves de API → LLM.',
  'chat_error.malformed_history':
    'Tivemos uma falha temporária nesta conversa. Já a corrigimos. Envie sua mensagem novamente.',
  'chat_error.request_rejected':
    'O provedor de IA rejeitou a requisição. Geralmente é uma incompatibilidade de modelo ou de parâmetros. Tente outro modelo em Conexões → Chaves de API → LLM.',
  'chat_error.managed_request_rejected':
    'A requisição foi rejeitada. Geralmente é uma incompatibilidade de modelo ou de parâmetros. Tente outro modelo em Conexões → Chaves de API → LLM.',
